CREATE TABLE artisan_specialties(id UUID PRIMARY KEY,code VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,description TEXT,active BOOLEAN NOT NULL DEFAULT TRUE);
INSERT INTO artisan_specialties(id,code,name) VALUES('20000000-0000-0000-0000-000000000001','sculpture','Sculpture'),('20000000-0000-0000-0000-000000000002','textile','Textile'),('20000000-0000-0000-0000-000000000003','pottery','Poterie'),('20000000-0000-0000-0000-000000000004','painting','Peinture'),('20000000-0000-0000-0000-000000000005','jewelry','Bijouterie'),('20000000-0000-0000-0000-000000000006','leatherwork','Travail du cuir'),('20000000-0000-0000-0000-000000000007','basketry','Vannerie'),('20000000-0000-0000-0000-000000000008','musical-instruments','Instruments de musique'),('20000000-0000-0000-0000-000000000009','woodwork','Travail du bois'),('20000000-0000-0000-0000-000000000010','digital-art','Art numérique') ON CONFLICT DO NOTHING;
CREATE TABLE artisan_profiles(partner_id UUID PRIMARY KEY REFERENCES partners(id),display_name VARCHAR(180) NOT NULL,story TEXT NOT NULL,craft_description TEXT NOT NULL,years_of_experience INT,country_code VARCHAR(2) NOT NULL,admin_level_1_id VARCHAR(100),city_id VARCHAR(100),locality_id VARCHAR(100),accepts_custom_orders BOOLEAN NOT NULL,international_shipping BOOLEAN NOT NULL,verification_status VARCHAR(30) NOT NULL,featured BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0,CHECK(years_of_experience IS NULL OR years_of_experience>=0));
CREATE TABLE artisan_profile_languages(partner_id UUID NOT NULL REFERENCES artisan_profiles(partner_id) ON DELETE CASCADE,language_code VARCHAR(35) NOT NULL,PRIMARY KEY(partner_id,language_code));CREATE TABLE artisan_profile_specialties(partner_id UUID NOT NULL REFERENCES artisan_profiles(partner_id) ON DELETE CASCADE,specialty_id UUID NOT NULL REFERENCES artisan_specialties(id),PRIMARY KEY(partner_id,specialty_id));
CREATE INDEX idx_artisan_search ON artisan_profiles(country_code,verification_status,featured);CREATE INDEX idx_artisan_location ON artisan_profiles(country_code,admin_level_1_id,city_id);
CREATE TABLE artisan_kyc_requirements(id BIGSERIAL PRIMARY KEY,country_code VARCHAR(2) NOT NULL,partner_type VARCHAR(40) NOT NULL,document_type VARCHAR(50) NOT NULL,required BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(country_code,partner_type,document_type));
INSERT INTO artisan_kyc_requirements(country_code,partner_type,document_type,required) VALUES('CM','ARTISAN','OWNER_IDENTITY',TRUE),('CM','ARTISAN','PORTFOLIO',TRUE),('CM','ARTIST','OWNER_IDENTITY',TRUE),('CM','ARTIST','PORTFOLIO',TRUE),('CM','CULTURAL_ASSOCIATION','BUSINESS_REGISTRATION',TRUE) ON CONFLICT DO NOTHING;
